  methods:{ cell(row,key){return key==="status"||key==="category"?this.t(row[key]||""):row[key]===null||row[key]===undefined?"—":row[key]}, t(key){return managementMessages[this.locale]?.[key]||messages[this.locale][key]||key}, async run(fn){this.error='';this.busy=true;try{await fn()}catch(e){this.error=e.response?.data?.detail||e.message||this.t('requestFailed')}finally{this.busy=false}}, openPage(id){this.page=id;this.pageNumber=0;Object.keys(this.filters).forEach(k=>this.filters[k]='');if(id!=='dashboard')this.loadPage(0)}, beginCreate(){this.editing=false;this.originalKey='';this.editor=this.page==='orders'?{order_number:'',customer_id:'',status:'PROCESSING',tracking_number:''}:this.page==='inventory'?{sku:'',name:'',stock:0,price:0}:this.page==='inquiries'?{customer_email:'',subject:'',body:'',category:'OTHER'}:{order_number:'',reason:''};this.showForm=true},beginEdit(row){this.editing=true;this.originalKey=this.page==='orders'?row.order_number:this.page==='inventory'?row.sku:row.id;this.editor=this.page==='orders'?{order_number:row.order_number,customer_id:row.customer_id,status:row.status,tracking_number:row.tracking_number||''}:this.page==='inventory'?{sku:row.sku,name:row.name,stock:row.stock,price:row.price}:this.page==='inquiries'?{customer_email:row.customer_email,subject:row.subject,body:row.body||'',category:row.category}:{order_number:row.order_number,reason:row.reason};this.showForm=true},saveManagement(){return this.run(async()=>{const path={orders:'/orders',inventory:'/products',inquiries:'/inquiries',refunds:'/refund-requests'}[this.page];if(this.page==='orders'){if(this.editing)await api.put(`${path}/${encodeURIComponent(this.originalKey)}`,{status:this.editor.status,tracking_number:this.editor.tracking_number});else await api.post(path,this.editor)}else if(this.page==='inventory'){if(this.editing)await api.put(`${path}/${encodeURIComponent(this.originalKey)}`,this.editor);else await api.post(path,this.editor)}else if(this.page==='inquiries'){if(this.editing)await api.put(`${path}/${this.originalKey}`,this.editor);else await api.post(path,{customer_email:this.editor.customer_email,subject:this.editor.subject,body:this.editor.body})}else{if(this.editing)await api.put(`${path}/${this.originalKey}`,{reason:this.editor.reason});else await api.post(path,{order_number:this.editor.order_number,reason:this.editor.reason})}this.showForm=false;await this.loadPage(this.pageNumber)})},searchPage(){this.loadPage(0)}, changePageSize(){this.loadPage(0)}, resetFilters(){Object.keys(this.filters).forEach(k=>this.filters[k]='');this.loadPage(0)}, loadPage(n){return this.run(async()=>{const path={orders:'/orders',refunds:'/refund-requests',inventory:'/products',inquiries:'/inquiries'}[this.page];const params={page:n,size:this.pageSize};Object.entries(this.filters).forEach(([k,v])=>{if(v!==''&&v!==null)params[k]=v});const result=(await api.get(path,{params})).data;this.rows=result.content||[];this.pageNumber=result.number||0;this.totalPages=result.totalPages||0;this.totalElements=result.totalElements||0})}, removeRow(row){if(!window.confirm(this.t('confirmDelete')))return;return this.run(async()=>{const key=this.page==='orders'?row.order_number:this.page==='inventory'?row.sku:row.id;const path={orders:'/orders',refunds:'/refund-requests',inventory:'/products',inquiries:'/inquiries'}[this.page];await api.delete(`${path}/${encodeURIComponent(key)}`);await this.loadPage(this.pageNumber);if(!this.rows.length&&this.pageNumber>0)await this.loadPage(this.pageNumber-1)})}, findOrder(){return this.run(async()=>{this.managedOrder=(await api.get(`/orders/${encodeURIComponent(this.manageOrderNumber)}`)).data})}, findManagedProduct(){return this.run(async()=>{this.managedProduct=(await api.get(`/products/${encodeURIComponent(this.manageSku)}`)).data})}, loadRefunds(){return this.loadPage(0)}, approveRefund(id){if(!window.confirm(this.t('confirmApprove')))return;return this.run(async()=>{await api.post(`/refund-requests/${id}/approve`);await this.loadPage(this.pageNumber)})},
    classify(){return this.run(async()=>{this.inquiryResult=(await api.post('/inquiries',this.form)).data})},
    lookupCustomer(){return this.run(async()=>{this.customerCreated=false;this.customer=null;this.orders=[];try{this.customer=(await api.get(`/customers/by-email/${encodeURIComponent(this.email)}`)).data;this.orders=(await api.get(`/customers/by-email/${encodeURIComponent(this.email)}/orders`)).data}catch(e){if(e.message==='Customer not found')throw new Error(this.t('customerNotFound'));throw e}})},
    createCustomer(){return this.run(async()=>{try{const saved=(await api.post('/customers',this.newCustomer)).data;this.customer=saved;this.email=saved.email;this.orders=[];this.customerCreated=true;this.newCustomer={name:'',email:''}}catch(e){if(e.response?.status===409)throw new Error(this.t('customerAlreadyExists'));throw e}})},
    lookupProduct(){return this.run(async()=>{this.product=(await api.get(`/products/${encodeURIComponent(this.sku)}`)).data})},
    prepareRefund(o){this.refund.order_number=o.order_number;window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})},
    createRefund(){return this.run(async()=>{this.refundResult=(await api.post('/refund-requests',this.refund)).data})}
  }
}
</script>
