w-x:auto;margin-top:18px}table{width:100%;border-collapse:collapse;min-width:680px;background:#fff}th,td{text-align:left;padding:12px;border-bottom:1px solid #e7eaf0;vertical-align:top}th{background:#f7f9fc;color:#536174;font-size:13px}td{font-size:14px}.management-heading{display:flex;justify-content:space-between;align-items:center}.management-heading h2{margin:0}.editor{margin:18px 0;padding:18px;background:#f7f9fc;border:1px solid #e7eaf0;border-radius:10px}.editor h3{margin:0 0 10px}.editor label{display:inline-block;vertical-align:top;width:min(260px,100%);margin:10px 14px 6px 0}.editor-actions{display:flex;gap:8px;margin-top:12px}.action-cell{white-space:nowrap}.filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin-top:12px}.filters label{min-width:150px;margin:0}.filters input,.filters select{margin-top:4px;padding:9px}.pagination{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:18px}.pagination label{display:flex;align-items:center;gap:6px;margin:0}.pagination select{padding:8px;border:1px solid #dce1e9;border-radius:8px;background:white}.pagination span{color:#536174;font-size:14px}.empty{text-align:center;color:#788397;padding:28px}.danger{background:#fae9e9;color:#a63838;padding:7px 10px}.customer-form{margin-top:18px;padding-top:14px;border-top:1px solid #e7eaf0}.customer-form h3{margin:0;color:#35445c;font-size:15px}.tag{display:inline-block;padding:3px 9px;border-radius:30px;background:#e4edff;color:#345cb4;font-size:12px;font-weight:700}.pending{background:#fff1da;color:#99611e}.order span{float:right;color:#4167bc}.order div{color:#66748a;font-size:13px}.link{background:transparent;color:#315bb5;padding:5px 0}.toast{position:fixed;bottom:20px;right:20px;background:#9e2c32;color:white;padding:14px 20px;border-radius:9px}@media(max-width:720px){.shell{padding:24px 14px}.grid{grid-template-columns:1fr}.inquiry{grid-row:auto}header{align-items:flex-start;gap:10px;flex-direction:column}.header-actions{flex-wrap:wrap}}
